internal final class METDebugAutoTOExtract extends RunBase
{
    /// <summary>
    /// Class entry point. The system will call this method when a designated menu 
    /// is selected or when execution starts and this class is set as the startup class.
    /// </summary>
    /// <param name = "_args">The specified arguments.</param>

    DialogField transferIdField;
    InventTransferId transferId;

}

Method.Source:
public Object dialog()
{
    Dialog dialog = super();

    dialog.caption("Select TO to extract");
    transferIdField = dialog.addField(extendedTypeStr(InventTransferId));
    return dialog;
}

public boolean getFromDialog()
{
    transferId = transferIdField.value();
    return super();
}

public void run()
{       
    if (transferId)
    {
        InventTransferTable inventTransferTable = InventTransferTable::find(transferId);
        METInventTransferTableExt metInventTransferTableExt = inventTransferTable.metInventTransferTableExt();
        if (inventTransferTable)
        {
            if ((inventTransferTable.InventLocationIdFrom == '031'
            || inventTransferTable.InventLocationIdFrom == '039'
            || inventTransferTable.InventLocationIdFrom == '651'
            || inventTransferTable.InventLocationIdFrom == '665'
            || inventTransferTable.InventLocationIdFrom == '849'
            || inventTransferTable.InventLocationIdFrom == '890'
            || inventTransferTable.InventLocationIdFrom == '891')
            && metInventTransferTableExt.IOMSyncCompleted == NoYes::Yes
            && (metInventTransferTableExt.OrderExtractStatus == METOrderExtractStatus::Open
            || metInventTransferTableExt.OrderExtractStatus == METOrderExtractStatus::ReadyForExtract))
            {
                ttsbegin;
                METTransferPickingListGenerationTaskContract   dataContract    = new METTransferPickingListGenerationTaskContract();
                METTransferPickingListGenerationTaskService    service         = new METTransferPickingListGenerationTaskService();

                dataContract.parmTransferId(transferId);
                dataContract.parmSkipFinalisationProcess(true);
                dataContract.parmTriggerBusinessEvent(true);

                service.process(dataContract);
                ttscommit;
            }
            else
            {
                throw error('TO doesnt meet criteria');
            }
        }
    }
}

/// <summary>
/// Class entry point. The system will call this method when a designated menu
/// is selected or when execution starts and this class is set as the startup class.
/// </summary>
/// <param name = "_args">The specified arguments.</param>
public static void main(Args _args)
{
    METDebugAutoTOExtract debug = new METDebugAutoTOExtract();

    if (debug.prompt())
    {
        debug.run();
    }
}
